	}
	if result.TotalCommitted != 3 {
		t.Errorf("TotalCommitted = %d, want 3", result.TotalCommitted)
	}
	if result.AgentPercentage != 0.0 {
		t.Errorf("AgentPercentage = %.1f%%, want 0.0%%", result.AgentPercentage)
	}
}

